/* Penyelesaian penuh UKKM Set 3: Matematik & Sains (dimuat selepas kertas dihantar) */
(window.UKKM_SOL = window.UKKM_SOL || {})[3] = {"mat":["<h5>🧭 Faham soalan</h5><p>Rajah menunjukkan 1, 3, 6 dan 10 titik pada empat susunan pertama. Cari bilangan titik dalam Rajah 8.</p><h5>💡 Strategi</h5><p>Setiap rajah menambah satu baris titik. Tambahan berturut-turut ialah 2, 3, 4 dan seterusnya; teruskan pola hingga rajah yang diminta.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Rajah 4 mempunyai 10 titik. Rajah 5: 10 + 5 = 15 titik; Rajah 6: 15 + 6 = 21 titik.</li><li>Rajah 7: 21 + 7 = 28 titik. Rajah 8: 28 + 8 = 36 titik.</li><li>Jawapan: <b>C</b> (36 titik).</li></ol><h5>🔍 Semak jawapan</h5><p>Formula nombor segi tiga memberi 8 × (8 + 1) ÷ 2 = 8 × 9 ÷ 2 = 36, sama dengan kiraan pola.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (64): 64 ialah 8², iaitu susunan segi empat sama.</li><li><b>B</b> (45): 45 ialah jumlah titik Rajah 9, bukan Rajah 8.</li><li><b>D</b> (28): 28 ialah jumlah titik Rajah 7; satu baris belum ditambah.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk susunan segi tiga, gunakan nombor rajah × (nombor rajah + 1) ÷ 2 sebagai semakan pantas.</p>",
"<h5>🧭 Faham soalan</h5><p>Tiga nombor genap yang bersebelahan berjumlah 138. Tentukan nombor yang paling besar.</p><h5>💡 Strategi</h5><p>Nombor genap berturutan berbeza sebanyak 2. Wakilkan yang terkecil dengan x, kemudian bina persamaan jumlah.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Tulis tiga nombor sebagai x, x + 2 dan x + 4.</li><li>x + (x + 2) + (x + 4) = 138, maka 3x + 6 = 138.</li><li>3x = 138 − 6 = 132; x = 132 ÷ 3 = 44. Nombornya 44, 46 dan 48.</li><li>Jawapan: <b>D</b> (48).</li></ol><h5>🔍 Semak jawapan</h5><p>44 + 46 + 48 = 138 dan setiap nombor genap; 48 memang yang terbesar.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (44): 44 ialah nombor terkecil.</li><li><b>B</b> (46): 46 ialah nombor tengah, iaitu 138 ÷ 3.</li><li><b>C</b> (47): Jika nombor bulat berturutan digunakan, nombornya ialah 45, 46 dan 47 kerana 45 + 46 + 47 = 138; yang terbesar ialah 47, tetapi 47 ialah nombor ganjil, bukan genap.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi tiga nombor berturutan dengan jarak sama, puratanya ialah nombor tengah.</p>",
"<h5>🧭 Faham soalan</h5><p>Modal RM 2 400 diberi faedah mudah 3.5% setahun selama 4 tahun. Cari jumlah modal bersama faedah.</p><h5>💡 Strategi</h5><p>Faedah mudah dikira atas modal asal pada setiap tahun. Gunakan modal × kadar × masa, kemudian tambah pada modal.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Tukar 3.5% kepada perpuluhan: 3.5 ÷ 100 = 0.035.</li><li>Faedah setahun = RM 2 400 × 0.035 = RM 84.00.</li><li>Faedah 4 tahun = RM 84.00 × 4 = RM 336.00.</li><li>Jumlah akhir = RM 2 400.00 + RM 336.00 = RM 2 736.00. Jawapan: <b>B</b> (RM 2 736.00).</li></ol><h5>🔍 Semak jawapan</h5><p>RM 2 736.00 − RM 2 400.00 = RM 336.00, tepat empat kali faedah setahun.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 2 754.06): RM 2 754.06 terhasil daripada faedah kompaun, sedangkan soalan menetapkan faedah mudah.</li><li><b>C</b> (RM 2 484.00): RM 2 484.00 ialah modal ditambah faedah setahun sahaja.</li><li><b>D</b> (RM 336.00): RM 336.00 ialah faedah sahaja, belum ditambah modal.</li></ul><h5>📌 Tip peperiksaan</h5><p>Kenal pasti perkataan “faedah mudah”; kadar tahunan sentiasa dikenakan pada modal asal.</p>",
"<h5>🧭 Faham soalan</h5><p>Empat isi padu dan harga jus diberi. Cari pek yang paling murah bagi setiap mililiter, bukan yang paling murah pada tanda harga.</p><h5>💡 Strategi</h5><p>Samakan unit isi padu, lalu bandingkan harga bagi 100 ml. Penyebut sama menjadikan perbandingan adil.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Tukar liter kepada mililiter: 1.2 L = 1 200 ml; 2 L = 2 000 ml.</li><li>A: RM 4.20 ÷ (500 ÷ 100) = RM 4.20 ÷ 5 = RM 0.84 bagi 100 ml.</li><li>B: RM 6.90 ÷ 7.5 = RM 0.92; C: RM 10.20 ÷ 12 = RM 0.85; D: RM 17.60 ÷ 20 = RM 0.88 bagi 100 ml.</li><li>RM 0.84 paling rendah. Jawapan: <b>A</b> (500 ml pada RM 4.20).</li></ol><h5>🔍 Semak jawapan</h5><p>Bagi 500 ml, lima unit 100 ml × RM 0.84 = RM 4.20, sepadan dengan harga asal.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (750 ml — RM 6.90): RM 0.92 bagi 100 ml lebih tinggi daripada RM 0.84.</li><li><b>C</b> (1.2 L — RM 10.20): RM 0.85 bagi 100 ml lebih tinggi sebanyak RM 0.01.</li><li><b>D</b> (2 L — RM 17.60): RM 0.88 bagi 100 ml masih lebih mahal walaupun peknya paling besar.</li></ul><h5>📌 Tip peperiksaan</h5><p>Banding harga seunit, bukan jumlah harga atau saiz pek.</p>",
"<h5>🧭 Faham soalan</h5><p>Carta pai mewakili 240 murid. Sektor badminton ditanda 75°. Cari bilangan murid dalam sektor itu.</p><h5>💡 Strategi</h5><p>Satu bulatan penuh ialah 360°. Bahagian murid sebanding dengan bahagian sudut sektor.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Baca sudut sektor badminton pada rajah: 75°.</li><li>Pecahan murid badminton = 75 ÷ 360 = 5 ÷ 24.</li><li>Bilangan murid = 5 ÷ 24 × 240 = 5 × 10 = 50.</li><li>Jawapan: <b>A</b> (50 orang murid).</li></ol><h5>🔍 Semak jawapan</h5><p>50 ÷ 240 × 360° = 75°, tepat seperti sudut pada carta.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (60): 60 orang bersamaan sektor 90°, iaitu bola jaring.</li><li><b>C</b> (75): 75 ialah ukuran sudut dalam darjah, bukan bilangan murid.</li><li><b>D</b> (180): 180 terhasil jika 75° tersalah baca sebagai 75% daripada 240.</li></ul><h5>📌 Tip peperiksaan</h5><p>Pada carta pai, tulis dahulu sudut sektor ÷ 360° sebelum darab jumlah orang.</p>",
"<h5>🧭 Faham soalan</h5><p>Pek A ada 10 biji telur pada RM 4.50; Pek B ada 30 biji pada RM 12.90. Banding kos untuk tepat 60 biji.</p><h5>💡 Strategi</h5><p>Kira bilangan pek yang diperlukan bagi kedua-dua pilihan, kemudian tolak kos Pek B daripada kos Pek A.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Pek A diperlukan: 60 ÷ 10 = 6 pek. Kos A = 6 × RM 4.50 = RM 27.00.</li><li>Pek B diperlukan: 60 ÷ 30 = 2 pek. Kos B = 2 × RM 12.90 = RM 25.80.</li><li>Penjimatan = RM 27.00 − RM 25.80 = RM 1.20.</li><li>Jawapan: <b>C</b> (RM 1.20).</li></ol><h5>🔍 Semak jawapan</h5><p>Sebiji telur berharga RM 0.45 dalam A dan RM 0.43 dalam B; beza RM 0.02 × 60 = RM 1.20.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 0.02): RM 0.02 ialah penjimatan sebiji telur sahaja.</li><li><b>B</b> (RM 0.60): RM 0.60 ialah penjimatan bagi 30 biji, separuh daripada keperluan.</li><li><b>D</b> (RM 8.40): RM 8.40 ialah beza harga satu Pek B dengan satu Pek A; bilangan telur berbeza.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk perbandingan pek, samakan jumlah barang dahulu sebelum menolak kos.</p>",
"<h5>🧭 Faham soalan</h5><p>Graf menunjukkan pengunjung Isnin hingga Jumaat. Jumlahkan hanya hari yang bilangannya lebih daripada 50 orang.</p><h5>💡 Strategi</h5><p>Baca setiap titik pada paksi menegak dan tapis mengikut syarat “melebihi 50”. Nilai tepat 50 tidak termasuk.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Daripada graf: Isnin 45, Selasa 60, Rabu 35, Khamis 70, Jumaat 50 orang.</li><li>Selasa 60 > 50 dan Khamis 70 > 50. Jumaat 50 = 50, jadi tidak dikira.</li><li>Jumlah yang diminta = 60 + 70 = 130 orang.</li><li>Jawapan: <b>B</b> (130 orang).</li></ol><h5>🔍 Semak jawapan</h5><p>Hanya dua titik terletak di atas garis 50; jumlahnya 130.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (70): 70 hanya bilangan pengunjung Khamis; Selasa tertinggal.</li><li><b>C</b> (180): 180 = 60 + 70 + 50; Jumaat sama dengan 50, bukan melebihi 50.</li><li><b>D</b> (260): 260 ialah jumlah kelima-lima hari, termasuk hari yang tidak memenuhi syarat.</li></ul><h5>📌 Tip peperiksaan</h5><p>Gariskan perkataan “melebihi”; ia bermaksud >, bukan ≥.</p>",
"<h5>🧭 Faham soalan</h5><p>Bekas kuboid berukuran 25 cm × 12 cm × 10 cm dan air sedalam 6 cm. Cari isi padu ruang kosong dalam liter.</p><h5>💡 Strategi</h5><p>Isi padu yang perlu ditambah ialah luas tapak didarab tinggi ruang kosong. Kemudian tukar cm³ kepada liter.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Tinggi ruang kosong = 10 − 6 = 4 cm.</li><li>Luas tapak = 25 × 12 = 300 cm².</li><li>Isi padu tambahan = 300 × 4 = 1 200 cm³.</li><li>Dengan 1 000 cm³ = 1 L, 1 200 ÷ 1 000 = 1.2 L. Jawapan: <b>A</b> (1.2 L).</li></ol><h5>🔍 Semak jawapan</h5><p>Isi padu penuh 25 × 12 × 10 = 3 000 cm³; isi padu sedia ada 25 × 12 × 6 = 1 800 cm³. Bezanya 1 200 cm³.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (1.8 L): 1.8 L ialah air yang sudah berada dalam bekas.</li><li><b>C</b> (3.0 L): 3.0 L ialah kapasiti penuh bekas.</li><li><b>D</b> (12 L): 12 L datang daripada membahagi 1 200 cm³ dengan 100, bukan 1 000.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk isi padu air tambahan, gunakan tinggi yang belum berisi air.</p>",
"<h5>🧭 Faham soalan</h5><p>Tin silinder berdiameter 14 cm dan tinggi 20 cm, diisi tiga perempat penuh. Cari isi padu air dalam cm³.</p><h5>💡 Strategi</h5><p>Gunakan isi padu silinder πr²h. Diameter mesti dibahagi dua untuk mendapatkan jejari; selepas itu ambil tiga perempat.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jejari r = 14 ÷ 2 = 7 cm.</li><li>Isi padu tin penuh = 22 ÷ 7 × 7² × 20 = 22 ÷ 7 × 49 × 20 = 3 080 cm³.</li><li>Isi padu air = 3 ÷ 4 × 3 080 = 3 × 770 = 2 310 cm³.</li><li>Jawapan: <b>C</b> (2 310 cm³).</li></ol><h5>🔍 Semak jawapan</h5><p>Satu perempat ruang kosong ialah 3 080 ÷ 4 = 770 cm³; 2 310 + 770 = 3 080 cm³.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (9 240 cm³): 9 240 cm³ boleh terhasil apabila diameter 14 cm digunakan sebagai jejari dalam bahagian tiga perempat.</li><li><b>B</b> (3 080 cm³): 3 080 cm³ ialah isi padu penuh, bukan tiga perempat.</li><li><b>D</b> (660 cm³): 660 ialah nilai daripada luas permukaan melengkung 2πrh yang didarab tiga perempat; unitnya cm², bukan cm³.</li></ul><h5>📌 Tip peperiksaan</h5><p>Labelkan jejari dan diameter berasingan sebelum memasukkan nilai ke dalam formula.</p>",
"<h5>🧭 Faham soalan</h5><p>Enam pelari tamat tanpa seri. Jamal ketiga, Kumar sejurus selepasnya, Hakim sebelum Farid, Farid sebelum Gopal, dan Irfan sejurus selepas Gopal. Cari tempat kelima.</p><h5>💡 Strategi</h5><p>Isi kedudukan yang sudah tetap dahulu. Kemudian kenal pasti pasangan bersebelahan Gopal dan Irfan sebelum meletakkan Hakim dan Farid.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jamal di tempat 3, maka Kumar di tempat 4. Ruang kosong ialah 1, 2, 5 dan 6.</li><li>Gopal mesti diikuti terus oleh Irfan. Pasangan ruang bersebelahan yang mungkin ialah 1 dan 2 atau 5 dan 6. Gopal tidak boleh di tempat 1 atau 2 kerana Hakim dan Farid mesti berada sebelum Gopal, jadi pasangan itu mesti tempat 5 dan 6; Gopal di tempat 5 dan Irfan di tempat 6.</li><li>Baki tempat 1 dan 2 diisi oleh Hakim dan Farid mengikut tertib: Hakim di tempat 1 dan Farid di tempat 2.</li><li>Jawapan: <b>A</b> (Gopal).</li></ol><h5>🔍 Semak jawapan</h5><p>Susunan lengkap ialah Hakim, Farid, Jamal, Kumar, Gopal, Irfan. Semua syarat dipenuhi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (Farid): Farid di tempat 2 kerana dia mesti selepas Hakim dan sebelum Gopal.</li><li><b>C</b> (Irfan): Irfan di tempat 6, sejurus selepas Gopal.</li><li><b>D</b> (Kumar): Kumar di tempat 4, sejurus selepas Jamal.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam teka susunan, tandakan tempat tetap dan pasangan “sejurus selepas” sebelum menyusun peserta lain.</p>",
"<h5>🧭 Faham soalan</h5><p>Pola tujuh manik berulang hingga 2 026 biji manik. Dalam setiap tujuh manik, tiga berwarna biru. Cari jumlah manik biru.</p><h5>💡 Strategi</h5><p>Bahagikan jumlah manik kepada kitaran lengkap dan baki. Kira biru dalam setiap bahagian secara berasingan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Satu kitaran ialah merah, biru, biru, kuning, hijau, biru, putih: 7 manik dan 3 biru.</li><li>2 026 ÷ 7 = 289 baki 3, kerana 7 × 289 = 2 023 dan 2 026 − 2 023 = 3.</li><li>Kitaran lengkap memberi 289 × 3 = 867 biru. Baki tiga manik ialah merah, biru, biru, jadi tambah 2.</li><li>Jumlah biru = 867 + 2 = 869. Jawapan: <b>B</b> (869 biji).</li></ol><h5>🔍 Semak jawapan</h5><p>289 kitaran menggunakan 2 023 manik; tambah baki 3 menjadi 2 026. Kiraan biru 867 + 2 = 869.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (1013): 1 013 menganggap separuh manik biru, sedangkan hanya 3 daripada setiap 7 manik berwarna biru.</li><li><b>C</b> (868): 868 diperoleh dengan menganggar 2 026 × 3/7 = 868.28… lalu dibundarkan ke bawah; kaedah ini mengabaikan baki kitaran terakhir yang sebenar.</li><li><b>D</b> (867): 867 ialah biru dalam kitaran lengkap sahaja; baki tiga manik belum dikira.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk pola berulang, gunakan kaedah bahagi dengan baki; jangan anggarkan pecahan biru pada hujung kitaran.</p>",
"<h5>🧭 Faham soalan</h5><p>Terdapat 48 syiling 20 sen dan 50 sen, bernilai RM 15.30. Cari bilangan syiling 50 sen.</p><h5>💡 Strategi</h5><p>Gunakan bilangan satu jenis sebagai pemboleh ubah. Jumlah bilangan memberi bilangan jenis lain; jumlah nilai memberi persamaan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Tukar RM 15.30 kepada sen: 15.30 × 100 = 1 530 sen.</li><li>Jika syiling 50 sen ada y keping, syiling 20 sen ada 48 − y keping.</li><li>50y + 20(48 − y) = 1 530; 50y + 960 − 20y = 1 530.</li><li>30y = 1 530 − 960 = 570; y = 570 ÷ 30 = 19. Jawapan: <b>A</b> (19 keping).</li></ol><h5>🔍 Semak jawapan</h5><p>Syiling 20 sen ialah 48 − 19 = 29. Nilainya 19 × 50 + 29 × 20 = 950 + 580 = 1 530 sen.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (24): 24 menganggap kedua-dua jenis syiling sama banyak, tetapi nilainya 24 × 50 + 24 × 20 = 1 680 sen, melebihi 1 530 sen.</li><li><b>C</b> (29): 29 ialah bilangan syiling 20 sen, bukan 50 sen.</li><li><b>D</b> (31): 31 menghampiri 1 530 ÷ 50, seolah-olah semua syiling bernilai 50 sen.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam soalan syiling, tukar semua wang kepada sen sebelum membina persamaan.</p>",
"<h5>🧭 Faham soalan</h5><p>Komisen 2.5% dikenakan pada RM 500 000 pertama dan 1.5% pada baki harga RM 680 000. Cari jumlah komisen dalam RM.</p><h5>💡 Strategi</h5><p>Pecahkan harga jualan mengikut dua julat kadar. Kira komisen setiap julat dan tambah; satu kadar tidak digunakan untuk seluruh harga.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Bahagian pertama = RM 500 000; komisen = 2.5 ÷ 100 × RM 500 000 = 0.025 × RM 500 000 = RM 12 500.</li><li>Baki harga = RM 680 000 − RM 500 000 = RM 180 000.</li><li>Komisen baki = 1.5 ÷ 100 × RM 180 000 = 0.015 × RM 180 000 = RM 2 700.</li><li>Jumlah komisen = RM 12 500 + RM 2 700 = RM 15 200. Jawapan: <b>RM 15 200</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>RM 500 000 + RM 180 000 = RM 680 000; kedua-dua bahagian harga telah diambil kira sekali sahaja.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Mengira 2.5% daripada keseluruhan RM 680 000; kadar itu hanya sah untuk bahagian pertama.</li><li>Mengira 1.5% daripada RM 680 000 tanpa mengasingkan RM 500 000 pertama.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi kadar berperingkat, lukis sempadan harga dan kenakan kadar pada setiap bahagian sahaja.</p>",
"<h5>🧭 Faham soalan</h5><p>Dua belas pekerja mampu menyiapkan pagar dalam 15 hari. Empat berhenti selepas lima hari. Cari hari tambahan untuk baki pekerja.</p><h5>💡 Strategi</h5><p>Ukur kerja dalam hari-pekerja. Tolak kerja yang sudah siap, lalu bahagikan baki kerja dengan bilangan pekerja yang tinggal.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jumlah kerja = 12 pekerja × 15 hari = 180 hari-pekerja.</li><li>Kerja dalam 5 hari pertama = 12 × 5 = 60 hari-pekerja. Baki = 180 − 60 = 120 hari-pekerja.</li><li>Pekerja tinggal = 12 − 4 = 8 orang. Masa baki = 120 ÷ 8 = 15 hari.</li><li>Jawapan: <b>C</b> (15 hari lagi).</li></ol><h5>🔍 Semak jawapan</h5><p>8 pekerja × 15 hari = 120 hari-pekerja; tambah 60 yang sudah siap memberi 180.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (22.5): 22.5 hari ialah 180 ÷ 8, seolah-olah kerja lima hari pertama belum dibuat.</li><li><b>B</b> (20): 20 hari ialah jumlah masa dari mula, iaitu 5 + 15; soalan meminta hari lagi.</li><li><b>D</b> (10): 10 hari ialah baki rancangan asal tanpa mengambil kira pekerja yang berhenti.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bezakan “hari lagi” daripada jumlah hari sejak kerja bermula.</p>",
"<h5>🧭 Faham soalan</h5><p>Plot batang dan daun memaparkan 15 jisim murid dalam kg. Cari nilai tengah apabila data disusun menaik.</p><h5>💡 Strategi</h5><p>Bagi bilangan data ganjil, median berada tepat pada kedudukan (bilangan data + 1) ÷ 2. Baca batang sebagai puluh dan daun sebagai sa.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Bilangan data ialah 15, maka kedudukan median = (15 + 1) ÷ 2 = 8.</li><li>Baca plot dari nilai terkecil: 32, 35, 38, 40, 41, 41, 46, 49. Nilai kelapan ialah 49.</li><li>Jawapan: <b>B</b> (49 kg).</li></ol><h5>🔍 Semak jawapan</h5><p>Terdapat tujuh nilai sebelum 49 dan tujuh nilai selepasnya dalam senarai 15 data.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (46 kg): 46 kg ialah nilai ketujuh, satu tempat sebelum median.</li><li><b>C</b> (51.5 kg): 51.5 kg ialah titik tengah antara nilai paling kecil 32 dan paling besar 71, bukan median.</li><li><b>D</b> (53 kg): 53 kg ialah mod, iaitu nilai paling kerap, bukan nilai tengah susunan.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk 15 data, terus cari nilai ke-8 selepas menyusun; jangan puratakan dua nilai.</p>",
"<h5>🧭 Faham soalan</h5><p>Pada graf Cartes, A ialah (−2, 5) dan B ialah (4, 1). Cari kecerunan garis AB.</p><h5>💡 Strategi</h5><p>Kecerunan ialah perubahan y dibahagi perubahan x. Baca kedua-dua koordinat dari rajah dan kekalkan tertib penolakan yang sama.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Daripada rajah, A(−2, 5) dan B(4, 1).</li><li>Perubahan menegak = 1 − 5 = −4; perubahan mengufuk = 4 − (−2) = 6.</li><li>Kecerunan = −4 ÷ 6 = −4/6 = −2/3.</li><li>Jawapan: <b>B</b> (−2/3).</li></ol><h5>🔍 Semak jawapan</h5><p>Garis menurun apabila bergerak dari kiri ke kanan, jadi kecerunannya patut negatif.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (−3/2): −3/2 menterbalikkan nisbah perubahan mengufuk dan menegak.</li><li><b>C</b> (2/3): 2/3 kehilangan tanda negatif walaupun garis menurun.</li><li><b>D</b> (3/2): 3/2 menterbalikkan nisbah dan juga kehilangan tanda negatif.</li></ul><h5>📌 Tip peperiksaan</h5><p>Semak tanda secara visual dahulu: garis menurun dari kiri ke kanan mempunyai kecerunan negatif.</p>",
"<h5>🧭 Faham soalan</h5><p>Semua label pada tiga kotak salah. Satu cabutan dari satu kotak mesti cukup untuk mengenal pasti semua isi.</p><h5>💡 Strategi</h5><p>Pilih kotak berlabel “Campur”. Oleh sebab label itu salah, isinya pasti sejenis buah sahaja; satu cabutan terus mengenal pasti jenis itu.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Kotak “Campur” tidak mungkin berisi campuran. Jika buah cabutan ialah epal, kotak itu berisi epal sahaja.</li><li>Dalam kes epal, kotak “Oren” tidak boleh berisi oren dan epal sudah ditemui; jadi kotak “Oren” berisi campuran, kotak “Epal” berisi oren.</li><li>Jika buah cabutan ialah oren, kotak “Campur” berisi oren. Kotak “Epal” mesti berisi campuran; kotak “Oren” berisi epal.</li><li>Dalam kedua-dua kes, semua isi dapat dikenal pasti. Jawapan: <b>D</b> (kotak berlabel “Campur”).</li></ol><h5>🔍 Semak jawapan</h5><p>Kedua-dua susunan yang mungkin meletakkan isi berbeza daripada setiap label, seperti syarat soalan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (Kotak berlabel “Epal”): Kotak ini berisi oren sahaja atau campuran. Jika sebiji oren dikeluarkan, kedua-dua isi itu mungkin kerana kedua-duanya mengandungi oren, jadi satu cabutan tidak menjamin semua isi dapat ditentukan.</li><li><b>B</b> (Kotak berlabel “Oren”): Kotak ini berisi epal sahaja atau campuran. Jika sebiji epal dikeluarkan, kedua-dua isi itu mungkin kerana kedua-duanya mengandungi epal, jadi satu cabutan tidak menjamin semua isi dapat ditentukan.</li><li><b>C</b> (Mana-mana kotak): Bukan sebarang kotak menjamin penyelesaian dengan satu cabutan, seperti yang ditunjukkan oleh kes kabur bagi pilihan A dan B.</li></ul><h5>📌 Tip peperiksaan</h5><p>Apabila semua label salah, label “Campur” memberi maklumat paling kuat: isi sebenar mesti satu jenis.</p>",
"<h5>🧭 Faham soalan</h5><p>Lapisan piramid ialah 1², 2², 3² dan seterusnya. Ada 120 oren; cari baki selepas membina piramid lengkap tertinggi.</p><h5>💡 Strategi</h5><p>Tambah kuasa dua mengikut lapisan hingga lapisan seterusnya melebihi 120. Kemudian tolak jumlah yang digunakan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jumlah 1 hingga 4 lapisan = 1 + 4 + 9 + 16 = 30 biji.</li><li>Lima lapisan memerlukan 30 + 25 = 55 biji; enam lapisan memerlukan 55 + 36 = 91 biji.</li><li>Tujuh lapisan memerlukan 91 + 49 = 140 biji, melebihi 120; maka tinggi maksimum ialah enam lapisan.</li><li>Baki oren = 120 − 91 = 29 biji. Jawapan: <b>29 biji</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>91 + 29 = 120. Baki 29 lebih kecil daripada 49 yang diperlukan untuk lapisan ketujuh.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Menggunakan 120 − 140 menghasilkan baki negatif kerana tujuh lapisan tidak dapat dibina.</li><li>Menolak 36 sahaja daripada 120; 36 ialah lapisan keenam, bukan jumlah enam lapisan.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk binaan lengkap, hentikan jumlah kumulatif tepat sebelum melebihi stok.</p>",
"<h5>🧭 Faham soalan</h5><p>Bil air RM 46 menggunakan tarif tiga blok. Jadual mengenakan RM 0.60 untuk 20 m³ pertama, RM 1.20 untuk 15 m³ berikutnya dan RM 2.00 selepas 35 m³.</p><h5>💡 Strategi</h5><p>Kira kos dua blok penuh terlebih dahulu. Baki bil menentukan penggunaan dalam blok terakhir.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Kos blok pertama = 20 × RM 0.60 = RM 12.00.</li><li>Kos blok kedua = 15 × RM 1.20 = RM 18.00. Kos 35 m³ pertama = RM 12.00 + RM 18.00 = RM 30.00.</li><li>Baki bil = RM 46.00 − RM 30.00 = RM 16.00. Pada RM 2.00 per m³, penggunaan tambahan = 16 ÷ 2 = 8 m³.</li><li>Jumlah penggunaan = 20 + 15 + 8 = 43 m³. Jawapan: <b>D</b> (43 m³).</li></ol><h5>🔍 Semak jawapan</h5><p>20 × 0.60 + 15 × 1.20 + 8 × 2.00 = 12 + 18 + 16 = RM 46.00.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (8 m³): 8 m³ hanya penggunaan dalam blok ketiga, bukan jumlah.</li><li><b>B</b> (23 m³): 23 m³ terhasil daripada 46 ÷ 2, seolah-olah semua air dikenakan kadar blok ketiga.</li><li><b>C</b> (37 m³): 37 diperoleh jika blok kedua dilangkau: 20 + (46 − 12) ÷ 2 = 20 + 17 = 37; pengiraan ini mengenakan kadar RM 2.00 terus selepas 20 m³ pertama dan mengabaikan 15 m³ pada kadar RM 1.20.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi tarif berblok, isi setiap blok mengikut turutan sebelum mengira baki bil.</p>",
"<h5>🧭 Faham soalan</h5><p>Terdapat 11 masa murid. Kuartil pertama dan ketiga ialah median separuh bawah dan atas, tanpa median keseluruhan. Cari perbezaannya.</p><h5>💡 Strategi</h5><p>Susun data menaik. Buang nilai tengah, kemudian ambil nilai tengah bagi setiap kumpulan lima data.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Susunan menaik: 9, 11, 12, 13, 14, 15, 16, 18, 20, 22, 25.</li><li>Median keseluruhan ialah nilai ke-6, 15. Separuh bawah: 9, 11, 12, 13, 14; kuartil pertama = 12.</li><li>Separuh atas: 16, 18, 20, 22, 25; kuartil ketiga = 20.</li><li>Julat antara kuartil = 20 − 12 = 8 minit. Jawapan: <b>A</b> (8 minit).</li></ol><h5>🔍 Semak jawapan</h5><p>Seperuh bawah dan atas masing-masing ada lima data; median 15 tidak dikira dua kali.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (11 minit): 11 = 22 − 11 diperoleh jika nilai ke-3 dan ke-9 dalam senarai asal yang belum disusun, iaitu 11 dan 22, diambil sebagai kuartil; data mesti disusun dahulu dan kuartil yang betul ialah 12 dan 20.</li><li><b>C</b> (15 minit): 15 minit ialah median keseluruhan, bukan beza dua kuartil.</li><li><b>D</b> (16 minit): 16 minit ialah julat penuh, 25 − 9.</li></ul><h5>📌 Tip peperiksaan</h5><p>Apabila 11 data diberi dengan kaedah ini, singkirkan nilai ke-6 sebelum membahagi dua kumpulan.</p>",
"<h5>🧭 Faham soalan</h5><p>Dalam 32 murid, 21 suka nasi lemak dan 17 suka roti canai. Cari had terkecil dan terbesar yang boleh suka kedua-duanya.</p><h5>💡 Strategi</h5><p>Gunakan pertindihan dua kumpulan. Had minimum berlaku apabila kesatuan memenuhi kelas; had maksimum dibatasi oleh kumpulan lebih kecil.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jumlah keahlian dua kumpulan = 21 + 17 = 38. Oleh sebab hanya 32 murid, pertindihan minimum = 38 − 32 = 6.</li><li>Had ini boleh dicapai: 15 suka nasi lemak sahaja, 11 suka roti canai sahaja, 6 suka kedua-duanya; jumlah = 32.</li><li>Pertindihan maksimum = min(21, 17) = 17, apabila semua 17 peminat roti canai juga suka nasi lemak.</li><li>Jawapan: <b>A</b> (minimum 6, maksimum 17).</li></ol><h5>🔍 Semak jawapan</h5><p>Bagi maksimum, 21 suka sekurang-kurangnya satu dan 32 − 21 = 11 tidak suka kedua-duanya; keadaan ini dibenarkan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (Minimum 6, maksimum 21): Maksimum 21 mustahil kerana hanya 17 murid suka roti canai.</li><li><b>C</b> (Minimum 6, maksimum 32): Maksimum 32 juga mustahil kerana kedua-dua kumpulan lebih kecil daripada 32.</li><li><b>D</b> (Minimum 15, maksimum 17): 15 bukan minimum pertindihan; 15 ialah 32 − 17, bilangan yang tidak suka roti canai.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk dua kumpulan, minimum pertindihan ialah jumlah saiz kumpulan tolak jumlah orang, jika hasilnya positif.</p>",
"<h5>🧭 Faham soalan</h5><p>Jujukan P bertambah 7 dan Q bertambah 4. Cari banyak nombor sepunya yang kurang daripada 200.</p><h5>💡 Strategi</h5><p>Cari satu sebutan sepunya dahulu. Seterusnya, sebutan sepunya berulang pada gandaan sepunya terkecil bagi dua beza jujukan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>19 terdapat dalam P kerana 5 + 2 × 7 = 19; juga dalam Q kerana 3 + 4 × 4 = 19. Ini sebutan sepunya pertama.</li><li>Gandaan sepunya terkecil bagi 7 dan 4 ialah 28. Oleh itu setiap sebutan sepunya seterusnya bertambah 28.</li><li>Senarai kurang daripada 200: 19, 47, 75, 103, 131, 159, 187. Sebutan berikutnya 187 + 28 = 215, sudah melebihi had.</li><li>Terdapat 7 nombor. Jawapan: <b>B</b> (7).</li></ol><h5>🔍 Semak jawapan</h5><p>Sebutan terakhir 187 memenuhi 187 < 200; 215 tidak memenuhi syarat.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (6): 6 tertinggal satu daripada tujuh sebutan, biasanya 19 atau 187.</li><li><b>C</b> (8): 8 termasuk 215, yang tidak kurang daripada 200.</li><li><b>D</b> (28): 28 ialah jarak antara sebutan sepunya, bukan bilangannya.</li></ul><h5>📌 Tip peperiksaan</h5><p>Selepas cari sebutan sepunya pertama, tambah GSTK dua beza jujukan hingga melepasi had.</p>",
"<h5>🧭 Faham soalan</h5><p>Jika setiap murid mendapat 5 gula-gula, baki 13; jika 7 setiap murid, kurang 9. Cari jumlah gula-gula.</p><h5>💡 Strategi</h5><p>Wakilkan bilangan murid dengan n. Kedua-dua keadaan menerangkan jumlah gula-gula yang sama, jadi samakan ungkapan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Daripada agihan 5 biji: jumlah gula-gula = 5n + 13.</li><li>Daripada agihan 7 biji: jumlah yang diperlukan 7n, tetapi kurang 9; jumlah sebenar = 7n − 9.</li><li>5n + 13 = 7n − 9; 13 + 9 = 7n − 5n; 22 = 2n; n = 11.</li><li>Jumlah gula-gula = 5 × 11 + 13 = 55 + 13 = 68. Jawapan: <b>D</b> (68 biji).</li></ol><h5>🔍 Semak jawapan</h5><p>Jika diberi 7 setiap murid, perlu 7 × 11 = 77; 77 − 68 = 9 biji, seperti soalan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (11): 11 ialah bilangan murid, bukan bilangan gula-gula.</li><li><b>B</b> (23): Jika “kurang 9” tersalah tulis sebagai tambah 9, persamaan menjadi 5n + 13 = 7n + 9, maka 2n = 4 dan n = 2; bilangan gula-gula = 5 × 2 + 13 = 23. Tanda yang betul ialah −9.</li><li><b>C</b> (55): 55 ialah 5 × 11; baki 13 belum ditambah.</li></ul><h5>📌 Tip peperiksaan</h5><p>“Berbaki” bermaksud tambah pada yang diagih; “tidak cukup” bermaksud tolak daripada yang diperlukan.</p>",
"<h5>🧭 Faham soalan</h5><p>Pengunjung naik 20% dari 2023 ke 2024, lalu turun 20% ke 2025. Jumlah 2025 ialah 4 800. Cari jumlah 2023.</p><h5>💡 Strategi</h5><p>Gunakan faktor perubahan berturutan. Kenaikan 20% ialah darab 1.20, penurunan 20% ialah darab 0.80.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Katakan bilangan pada 2023 ialah x. Tahun 2024 = 1.20x.</li><li>Tahun 2025 = 0.80 × 1.20x = 0.96x.</li><li>0.96x = 4 800, maka x = 4 800 ÷ 0.96 = 5 000.</li><li>Jawapan: <b>D</b> (5 000 orang pada 2023).</li></ol><h5>🔍 Semak jawapan</h5><p>2024: 5 000 × 1.20 = 6 000; 2025: 6 000 × 0.80 = 4 800.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (4 608): 4 608 ialah 4 800 × 0.96; itu menggunakan faktor perubahan ke arah yang salah.</li><li><b>B</b> (4 800): 4 800 menganggap naik dan turun 20% saling membatalkan, walaupun asas peratus berubah.</li><li><b>C</b> (4 992): 4 992 ialah 4 800 × 1.04; faktor songsang yang betul ialah bahagi 0.96.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi perubahan peratus berturutan, darab faktor perubahan sebelum menyongsangkan untuk mencari nilai asal.</p>",
"<h5>🧭 Faham soalan</h5><p>Nisbah lelaki kepada perempuan asal ialah 3 : 5. Enam lelaki masuk dan dua perempuan keluar, kemudian bilangan sama. Cari perempuan asal.</p><h5>💡 Strategi</h5><p>Wakilkan bahagian nisbah dengan k. Nisbah 1 : 1 selepas perubahan bermaksud bilangan baharu kedua-dua kumpulan sama.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Lelaki asal = 3k dan perempuan asal = 5k.</li><li>Selepas perubahan, lelaki = 3k + 6 dan perempuan = 5k − 2. Samakan: 3k + 6 = 5k − 2.</li><li>6 + 2 = 5k − 3k; 8 = 2k; k = 4.</li><li>Perempuan asal = 5 × 4 = 20 orang. Jawapan: <b>C</b> (20 orang).</li></ol><h5>🔍 Semak jawapan</h5><p>Lelaki baharu = 3 × 4 + 6 = 18; perempuan baharu = 5 × 4 − 2 = 18. Nisbahnya 1 : 1.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (12): 12 ialah bilangan lelaki asal, iaitu 3 × 4.</li><li><b>B</b> (18): 18 ialah bilangan perempuan selepas dua orang keluar.</li><li><b>D</b> (32): 32 ialah jumlah ahli asal, 12 + 20.</li></ul><h5>📌 Tip peperiksaan</h5><p>Letak perkataan “asal” pada pemboleh ubah sebelum mengubah bilangan ahli.</p>",
"<h5>🧭 Faham soalan</h5><p>Daripada 40 murid, 25 dalam Sains, 18 dalam Robotik dan 7 tiada kelab. Pilih hanya daripada peserta sekurang-kurangnya satu kelab. Cari peluang Sains sahaja.</p><h5>💡 Strategi</h5><p>Tentukan ruang sampel bersyarat dahulu. Gunakan kaedah dua set untuk cari pertindihan dan bilangan Sains sahaja.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Peserta sekurang-kurangnya satu kelab = 40 − 7 = 33 orang.</li><li>Peserta kedua-dua kelab = 25 + 18 − 33 = 10 orang.</li><li>Peserta Sains sahaja = 25 − 10 = 15 orang.</li><li>Kebarangkalian = 15/33 = (15 ÷ 3)/(33 ÷ 3) = 5/11. Jawapan: <b>C</b> (5/11).</li></ol><h5>🔍 Semak jawapan</h5><p>Sains sahaja 15, kedua-dua 10 dan Robotik sahaja 18 − 10 = 8; 15 + 10 + 8 = 33.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (10/33): 10/33 ialah peluang peserta kedua-dua kelab, bukan Sains sahaja.</li><li><b>B</b> (3/8): 3/8 = 15/40 menggunakan seluruh kelas sebagai ruang sampel.</li><li><b>D</b> (5/8): 5/8 = 25/40 menggunakan seluruh kelas dan memasukkan peserta kedua-dua kelab.</li></ul><h5>📌 Tip peperiksaan</h5><p>Baca frasa “dipilih daripada” untuk menentukan penyebut kebarangkalian.</p>",
"<h5>🧭 Faham soalan</h5><p>Sektor kipas berjejari 21 cm dan sudut pusat 120°. Renda meliputi lengkok serta dua sisi lurus. Cari panjang keseluruhan.</p><h5>💡 Strategi</h5><p>Panjang lengkok ialah pecahan sudut daripada lilitan penuh. Tambah kedua-dua jejari untuk memperoleh perimeter sektor.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Pecahan bulatan = 120° ÷ 360° = 1/3.</li><li>Lilitan penuh = 2 × π × r = 2 × 22/7 × 21 = 132 cm.</li><li>Panjang lengkok = 1/3 × 132 = 44 cm.</li><li>Panjang renda = 44 + 21 + 21 = 86 cm. Jawapan: <b>86 cm</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>Dua jejari berjumlah 42 cm; 86 − 42 = 44 cm, sama dengan panjang lengkok.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Menjawab 44 cm sahaja kerana terlupa kedua-dua sisi lurus.</li><li>Menambah satu jejari sahaja lalu mendapat 65 cm; sempadan mempunyai dua jejari.</li></ul><h5>📌 Tip peperiksaan</h5><p>Perkataan “seluruh sempadan” bagi sektor bermaksud lengkok tambah dua jejari.</p>",
"<h5>🧭 Faham soalan</h5><p>Dewasa RM 12, kanak-kanak RM 7, warga emas RM 5. Jumlah 200 tiket dan RM 1 890; tiket kanak-kanak dua kali warga emas. Cari tiket dewasa.</p><h5>💡 Strategi</h5><p>Wakilkan warga emas dengan w; nyatakan dua kategori lain dalam w. Gunakan jumlah kutipan untuk membina satu persamaan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Warga emas = w, kanak-kanak = 2w, dewasa = 200 − w − 2w = 200 − 3w.</li><li>12(200 − 3w) + 7(2w) + 5w = 1 890.</li><li>2 400 − 36w + 14w + 5w = 1 890; 2 400 − 17w = 1 890; 17w = 510; w = 30.</li><li>Dewasa = 200 − 3 × 30 = 110. Jawapan: <b>D</b> (110 tiket).</li></ol><h5>🔍 Semak jawapan</h5><p>Kanak-kanak 60 dan warga emas 30; 110 + 60 + 30 = 200, manakala 110 × 12 + 60 × 7 + 30 × 5 = RM 1 890.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (30): 30 ialah bilangan tiket warga emas.</li><li><b>B</b> (60): 60 ialah bilangan tiket kanak-kanak.</li><li><b>C</b> (98): 98 boleh terhasil jika semua tiket bukan dewasa dianggap berharga RM 7, mengabaikan harga warga emas.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam soalan tiga kategori, gunakan hubungan “dua kali” untuk kurangkan bilangan pemboleh ubah.</p>",
"<h5>🧭 Faham soalan</h5><p>Dua puluh pekerja menyiapkan hanya satu perempat kerja dalam 10 hari. Mereka masih ada 20 hari daripada rancangan 30 hari. Cari pekerja tambahan.</p><h5>💡 Strategi</h5><p>Gunakan kadar sebenar dalam 10 hari pertama. Tukar kerja kepada hari-pekerja, kemudian bahagi baki kerja dengan baki masa.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Kerja satu perempat = 20 pekerja × 10 hari = 200 hari-pekerja.</li><li>Kerja penuh = 200 × 4 = 800 hari-pekerja; baki kerja = 800 − 200 = 600 hari-pekerja.</li><li>Masa yang tinggal = 30 − 10 = 20 hari. Pekerja diperlukan = 600 ÷ 20 = 30 orang.</li><li>Pekerja tambahan = 30 − 20 = 10 orang. Jawapan: <b>B</b> (10 orang).</li></ol><h5>🔍 Semak jawapan</h5><p>30 pekerja × 20 hari = 600 hari-pekerja; tambah 200 yang sudah siap memberi 800.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (3): Jika jumlah kerja dianggarkan mengikut rancangan asal, 20 × 30 = 600 hari-pekerja, baki kerja ialah 3/4 × 600 = 450 hari-pekerja; 450 ÷ 20 = 22.5, jadi 23 pekerja diperlukan dan tambahan = 23 − 20 = 3. Anggaran ini mengabaikan kadar sebenar yang lebih perlahan dalam 10 hari pertama.</li><li><b>C</b> (30): 30 ialah jumlah pekerja yang diperlukan untuk baki kerja, bukan tambahan.</li><li><b>D</b> (40): 40 tambahan bermaksud 60 pekerja dan menganggap baki tiga perempat perlu siap dalam 10 hari, bukan 20.</li></ul><h5>📌 Tip peperiksaan</h5><p>Apabila kemajuan sebenar diberi, gunakan kadar sebenar itu dan bezakan jumlah pekerja daripada tambahan.</p>",
"<h5>🧭 Faham soalan</h5><p>Dalam rajah wau, pepenjuru berserenjang di O. AO = 5 cm, OC = 16 cm dan BO = OD = 12 cm. Benang mengikut empat sisi luar.</p><h5>💡 Strategi</h5><p>Setiap sisi menjadi hipotenus segi tiga bersudut tegak. Gunakan teorem Pythagoras untuk dua panjang sisi yang berbeza, lalu gandakan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Daripada rajah, segi tiga AOB mempunyai kaki 5 cm dan 12 cm. AB = √(5² + 12²) = √(25 + 144) = √169 = 13 cm.</li><li>Segi tiga BOC mempunyai kaki 12 cm dan 16 cm. BC = √(12² + 16²) = √(144 + 256) = √400 = 20 cm.</li><li>Oleh sebab BO = OD, AD = AB = 13 cm dan CD = BC = 20 cm.</li><li>Perimeter = 13 + 20 + 20 + 13 = 66 cm. Jawapan: <b>C</b> (66 cm).</li></ol><h5>🔍 Semak jawapan</h5><p>Panjang sisi sepasang ialah 13 + 20 = 33 cm; dua pasangan memberi 33 × 2 = 66 cm.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (33 cm): 33 cm hanya jumlah dua sisi, bukan seluruh sempadan.</li><li><b>B</b> (45 cm): 45 cm ialah jumlah panjang buluh AC + BD = (5 + 16) + (12 + 12), bukan sisi luar.</li><li><b>D</b> (90 cm): 90 cm terhasil jika kaki segi tiga dijumlahkan menggantikan hipotenus.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi pepenjuru serenjang, cari sisi luar dengan Pythagoras sebelum mengira perimeter.</p>"],
"sains":["<h5>🧠 Konsep utama</h5><p>Sel tumbuhan mempunyai beberapa struktur khusus yang membezakannya daripada sel haiwan bagi tujuan sokongan mekanikal. Salah satu struktur tersebut ialah dinding sel, iaitu lapisan luar tegar yang menyelaputi membran sel tumbuhan. Dinding sel terbina daripada gentian selulosa yang bersifat tegar, kuat dan telap sepenuhnya. Kehadiran selulosa ini memberikan kekuatan fizikal kepada tumbuhan untuk menahan tekanan turgor apabila vakuol menyerap air, sekali gus membolehkan sel tumbuhan mengekalkan bentuk yang tetap serta memberikan sokongan mekanikal kepada seluruh tumbuhan.</p><h5>✅ Mengapa jawapan B betul</h5><p>Dinding sel yang dibina daripada selulosa bersifat tegar dan kukuh, berfungsi melindungi sel, mengekalkan bentuk sel yang tetap dan menyokong struktur tumbuhan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Membran sel ialah lapisan separa telap yang fleksibel dan berfungsi mengawal pergerakan bahan masuk dan keluar dari sel, bukan memberi bentuk tetap.</li><li><b>C</b> — Nukleus mengandungi bahan genetik kromosom dan berfungsi mengawal segala aktiviti biokimia serta pembahagian di dalam sel.</li><li><b>D</b> — Sitoplasma ialah bendalir seperti jeli yang bertindak sebagai medium bagi tindak balas metabolik sel dan menempatkan pelbagai organel.</li></ul><h5>📌 Ingat</h5><p>Dinding sel yang mengandungi gentian selulosa memberikan sokongan dan bentuk tetap kepada sel tumbuhan; sel haiwan tiada dinding sel maka bentuknya tidak tetap.</p>",
"<h5>🧠 Konsep utama</h5><p>Homeostasis merupakan proses kawal atur persekitaran dalam badan organisma supaya keadaan fizikal dan kimianya sentiasa stabil pada julat optimum. Suhu badan normal manusia ialah sekitar 37 °C. Apabila seseorang berlari di bawah cuaca panas, haba terhasil daripada respirasi sel otot yang cergas dan suhu persekitaran yang tinggi, menyebabkan suhu badan mula meningkat. Pusat kawalan suhu di hipotalamus mengesan perubahan ini lalu mencetuskan mekanisme pembetulan: kelenjar peluh dirangsang untuk merembeskan lebih banyak peluh agar haba pendam penyejatan disingkirkan dari kulit, manakala salur darah pada kulit mengalami pemvasodilatan (mengembang) supaya lebih banyak darah mengalir ke permukaan kulit untuk membebaskan haba ke persekitaran secara sinaran.</p><h5>✅ Mengapa jawapan B betul</h5><p>Penambahan perembesan peluh meningkatkan pembebasan haba melalui penyejatan, manakala pengembangan salur darah di kulit memudahkan pemindahan haba dari darah ke udara luar.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Kurang berpeluh dan pengecutan salur darah (pemvasocerutan) ialah tindak balas badan dalam persekitaran sejuk bagi mengekalkan haba badan.</li><li><b>C</b> — Menggigil ialah pengecutan otot secara tidak terkawal untuk menjana haba apabila badan berasa sejuk, bukan semasa berada dalam keadaan panas.</li><li><b>D</b> — Salur darah kulit akan mengembang (bukan mengecut) apabila badan panas supaya haba dari darah dapat disingkirkan dengan cekap ke persekitaran.</li></ul><h5>📌 Ingat</h5><p>Kawal atur suhu ketika panas: kelenjar peluh lebih aktif (berpeluh bertambah) dan salur darah kulit mengembang (pemvasodilatan) untuk menyingkirkan haba berlebihan.</p>",
"<h5>🧠 Konsep utama</h5><p>Model balang loceng digunakan untuk mensimulasikan mekanisme pernafasan pada sistem respirasi manusia. Dalam model ini, balang kaca mewakili rongga toraks, tiub kaca berbentuk Y mewakili trakea dan bronkus, belon mewakili peparu, manakala kepingan getah nipis di dasar balang bertindak sebagai diafragma. Apabila kepingan getah ditarik ke bawah, tindakan ini menyerupai pengecutan dan pendataran diafragma semasa proses menarik nafas. Pergerakan ini menyebabkan isi padu ruang udara di dalam balang loceng bertambah. Mengikut Hukum Boyle, pertambahan isi padu ini menyebabkan tekanan udara di dalam balang loceng berkurang berbanding tekanan atmosfera luar, lalu udara masuk melalui tiub kaca dan mengembangkan belon.</p><h5>✅ Mengapa jawapan A betul</h5><p>Menarik kepingan getah ke bawah meningkatkan isi padu ruang balang, merendahkan tekanan udara di dalamnya, lantas membolehkan udara luar masuk lalu belon mengembang.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Pengurangan isi padu dan peningkatan tekanan berlaku apabila kepingan getah ditolak ke atas, yang mewakili proses menghembus nafas.</li><li><b>C</b> — Pertambahan isi padu di dalam ruang tertutup akan mengurangkan tekanan udara, bukan meningkatkannya.</li><li><b>D</b> — Isi padu ruang balang bertambah (bukan berkurang) apabila kepingan getah ditarik ke bahagian bawah balang.</li></ul><h5>📌 Ingat</h5><p>Tarik nafas: kepingan getah ditarik ke bawah (diafragma mendatar) → isi padu toraks bertambah → tekanan berkurang → belon mengembang (peparu mengembang).</p>",
"<h5>🧠 Konsep utama</h5><p>Gas oksigen diangkut oleh sel darah merah ke seluruh sel tisu badan melalui pengikatan dengan hemoglobin untuk membentuk oksihemoglobin. Karbon monoksida (CO) merupakan gas toksik tanpa warna dan bau yang terbebas akibat pembakaran tidak lengkap bahan api atau tembakau dalam asap rokok. Secara kimia, pigmen hemoglobin mempunyai afiniti atau kecenderungan bergabung dengan gas karbon monoksida kira-kira 200 hingga 250 kali lebih kuat berbanding kecenderungannya dengan gas oksigen. Apabila karbon monoksida disedut masuk ke dalam peparu dan meresap ke dalam kapilari darah, ia akan segera bergabung secara kuat dengan hemoglobin membentuk sebatian stabil yang dipanggil karboksihemoglobin, mengakibatkan tapak pengikatan oksigen tersumbat.</p><h5>✅ Mengapa jawapan C betul</h5><p>Karbon monoksida bergabung jauh lebih mudah dan kuat dengan hemoglobin berbanding oksigen, mengurangkan bilangan molekul hemoglobin bebas yang boleh mengangkut oksigen.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Kerosakan dinding alveolus dan kehilangan keanjalan tisu peparu (emfisema) disebabkan oleh tar rokok dan bahan merengsa, bukan sifat kimia karbon monoksida.</li><li><b>B</b> — Karbon monoksida tidak melemahkan otot diafragma secara langsung, sebaliknya bertindak pada keupayaan kimia pigmen darah.</li><li><b>D</b> — Karbon monoksida tidak menukarkan gas oksigen kepada gas karbon dioksida di dalam aliran darah.</li></ul><h5>📌 Ingat</h5><p>Karbon monoksida mempunyai afiniti amat tinggi terhadap hemoglobin dan membentuk karboksihemoglobin yang stabil, merencatkan pengangkutan oksigen oleh sel darah merah.</p>",
"<h5>🧠 Konsep utama</h5><p>Arteri membawa darah keluar dari jantung, manakala vena membawa darah kembali ke jantung. Tekanan darah dalam vena lebih rendah berbanding arteri. Oleh itu, injap pada kebanyakan vena membantu mengekalkan aliran sehala ke jantung, terutamanya apabila darah dari kaki perlu bergerak melawan graviti. Kandungan oksigen tidak menentukan jenis salur darah: vena pulmonari membawa darah beroksigen dari peparu ke jantung.</p><h5>✅ Mengapa jawapan D betul</h5><p>Vena mempunyai injap yang menghalang darah mengalir balik apabila tekanan darah rendah.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Arteri membawa darah keluar dari jantung pada tekanan tinggi dan tidak mempunyai injap di sepanjang salurnya.</li><li><b>B</b> — Kapilari berdinding sangat nipis untuk pertukaran bahan dan tidak mempunyai injap.</li><li><b>C</b> — Aorta ialah arteri utama, bukan vena. Injap aorta berada pada pangkalnya di jantung, bukan di sepanjang salur aorta seperti injap vena.</li></ul><h5>📌 Ingat</h5><p>Kenal pasti salur darah melalui arah aliran: arteri keluar dari jantung, vena kembali ke jantung.</p>",
"<h5>🧠 Konsep utama</h5><p>Tumbuhan vaskular bergantung kepada dua tisu pengangkut utama di dalam berkas vaskular, iaitu xilem dan floem. Xilem terletak pada bahagian dalam batang dan mengangkut air serta garam mineral terlarut dari akar ke daun. Floem pula terletak di lapisan luar batang, tepat di bawah lapisan kulit kayu (epidermis dan korteks), dan berfungsi mengangkut makanan (sukrosa dan asid amino) hasil proses fotosintesis dari daun ke bahagian lain seperti akar dan buah melalui proses translokasi. Apabila sekeping gelang kulit batang dibuang sepenuhnya, tisu floem terputus manakala salur xilem di bahagian tengah kekal utuh. Akibatnya, makanan yang dihasilkan oleh daun tidak dapat diangkut ke akar dan terkumpul di bahagian atas gelang, menyebabkannya membengkak.</p><h5>✅ Mengapa jawapan B betul</h5><p>Pembuangan tisu floem menyekat laluan translokasi makanan, mengakibatkan hasil fotosintesis terkumpul di atas bahagian gelang kulit sehingga batang membengkak.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Air diangkut oleh xilem yang terletak di bahagian dalam batang dan tidak terjejas oleh pembuangan kulit luar, maka air tetap mengalir ke daun.</li><li><b>C</b> — Pembengkakan batang berpunca daripada pengumpulan bahan organik dan bukan kerana penyerapan gas oksigen yang berlebihan.</li><li><b>D</b> — Garam mineral diangkut ke atas bersama aliran transpirasi air melalui xilem dari akar, bukan melalui floem.</li></ul><h5>📌 Ingat</h5><p>Kedudukan berkas vaskular batang dikotiledon: floem di luar, xilem di dalam. Menggelang kulit memotong floem → pengumpulan makanan di atas gelang → membengkak.</p>",
"<h5>🧠 Konsep utama</h5><p>Pembiakan merupakan proses biologi bagi menghasilkan zuriat baharu dan dibahagikan kepada pembiakan seks serta pembiakan aseks. Pembiakan vegetatif ialah salah satu bentuk pembiakan aseks yang berlaku pada tumbuhan, di mana individu baharu tumbuh daripada bahagian vegetatif tumbuhan induk seperti akar, batang, daun atau tunas adventitius tanpa melibatkan pembentukan bunga, gamet atau persenyawaan. Pokok setawar (<i>Bryophyllum</i>) mempunyai kebolehan membentuk tunas vegetatif khas di sepanjang takuk tepi daunnya. Apabila daun setawar bersentuhan dengan tanah yang lembap, tunas adventitius ini akan bertunas dan menghasilkan akar serta pucuk baharu yang akhirnya berkembang menjadi anak pokok bebas yang seiras dengan pokok induk.</p><h5>✅ Mengapa jawapan D betul</h5><p>Pertumbuhan anak pokok daripada struktur daun pokok setawar merupakan contoh klasik pembiakan aseks secara pembiakan vegetatif.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Pembiakan seks memerlukan penglibatan bunga, gamet jantan (debunga) dan gamet betina (ovul) serta proses persenyawaan.</li><li><b>B</b> — Pembentukan spora ialah pembiakan aseks menggunakan sporangium yang lazimnya berlaku pada tumbuhan bukan vaskular, lumut, kulat dan paku-pakis.</li><li><b>C</b> — Pembelahan dedua ialah kaedah pembiakan aseks bagi organisma unisel seperti bakteria dan <i>Amoeba</i> melalui pembahagian satu sel matang kepada dua sel anak.</li></ul><h5>📌 Ingat</h5><p>Contoh struktur pembiakan vegetatif: daun (setawar, begonia), batang rayap (rumput, strawberi), rizom (halia), umbisi (keladi) dan bebawang (bawang).</p>",
"<h5>🧠 Konsep utama</h5><p>Gizi seimbang memerlukan pengambilan nutrien yang lengkap termasuk karbohidrat, protein, lemak, vitamin, mineral, serat dan air. Vitamin D memainkan peranan penting dalam menggalakkan penyerapan kalsium dan fosforus daripada salur pencernaan ke dalam aliran darah, yang amat diperlukan untuk pemendapan mineral bagi membina serta menguatkan tulang dan gigi yang sihat. Sumber vitamin D boleh diperoleh daripada pemakanan seperti susu, ikan berlemak dan telur, serta sintesis semula jadi oleh sel kulit apabila terdedah kepada sinaran ultraungu cahaya Matahari pagi. Kekurangan vitamin D atau kalsium pada kanak-kanak menyebabkan tulang gagal mengalami mineralisasi yang sempurna, menjadikannya rapuh, lembut dan melengkung di bawah beban badan (penyakit riket).</p><h5>✅ Mengapa jawapan C betul</h5><p>Tulang lembut dan bengkok merupakan tanda penyakit riket akibat kekurangan vitamin D, yang boleh diatasi dengan meminum susu berkalsium dan pendedahan kepada sinaran Matahari pagi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Kekurangan vitamin A membawa kepada masalah kesihatan penglihatan seperti rabun malam dan kerosakan kornea.</li><li><b>B</b> — Kekurangan vitamin C mengakibatkan penyakit skurvi yang dicirikan oleh gusi bengkak dan berdarah serta luka lambat sembuh.</li><li><b>D</b> — Kekurangan zat besi (ferum) menyebabkan penyakit anemia kerana pengurangan sintesis molekul hemoglobin dalam sel darah merah.</li></ul><h5>📌 Ingat</h5><p>Kekurangan vitamin D atau kalsium pada kanak-kanak mengakibatkan riket (tulang lembut dan bengkok). Cahaya Matahari pagi merangsang kulit menghasilkan vitamin D.</p>",
"<h5>🧠 Konsep utama</h5><p>Keimunan ialah keupayaan sistem pertahanan badan untuk melawan jangkitan patogen khusus. Keimunan dibahagikan kepada dua kategori: keimunan aktif dan keimunan pasif. Keimunan aktif berlaku apabila badan sendiri dirangsang untuk menghasilkan antibodi melalui tindak balas limfosit. Sebaliknya, keimunan pasif berlaku apabila badan menerima bekalan molekul antibodi sedia ada dari sumber luar tanpa perlu menghasilkannya sendiri. Keimunan pasif ini bersifat sementara kerana antibodi luar akan terurai selepas satu tempoh masa. Apabila bayi menerima antibodi daripada ibu secara biologi melalui susu ibu (terutamanya kolostrum) atau melalui plasenta semasa dalam kandungan, keimunan ini tergolong sebagai keimunan pasif semula jadi.</p><h5>✅ Mengapa jawapan B betul</h5><p>Bayi menerima antibodi siap daripada susu ibu secara semula jadi tanpa sistem imun bayi sendiri menghasilkan antibodi tersebut, menjadikannya keimunan pasif semula jadi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Keimunan aktif semula jadi diperoleh apabila seseorang dijangkiti patogen sebenar dan sembuh, lalu sistem imun badan menghasilkan antibodinya sendiri.</li><li><b>C</b> — Keimunan aktif buatan diperoleh melalui suntikan vaksin (antigen mati atau dilemahkan) yang merangsang badan membina antibodi sendiri.</li><li><b>D</b> — Keimunan pasif buatan diperoleh apabila pesakit disuntik dengan antiserum atau antivenom yang mengandungi antibodi siap dari luar secara klinikal.</li></ul><h5>📌 Ingat</h5><p>Keimunan pasif semula jadi: pemindahan antibodi sedia ada secara semula jadi daripada ibu kepada anak melalui tali pusat (plasenta) atau susu ibu.</p>",
"<h5>🧠 Konsep utama</h5><p>Kitar karbon merupakan kitar biogeokimia yang mengawal atur dan mengekalkan kepekatan gas karbon dioksida di dalam atmosfera Bumi. Gas karbon dioksida sentiasa dibebaskan ke atmosfera melalui pelbagai proses semula jadi dan aktiviti manusia, antaranya respirasi sel oleh hidupan, penguraian bahan organik mati oleh bakteria dan kulat pengurai, serta pembakaran bahan api fosil (petroleum, gas asli dan arang batu). Satu-satunya proses biologi berskala besar yang menyerap dan menyingkirkan gas karbon dioksida daripada atmosfera ialah fotosintesis. Tumbuhan hijau dan fitoplankton menyerap karbon dioksida dari udara untuk bertindak balas dengan air menggunakan tenaga cahaya bagi menghasilkan molekul glukosa dan membebaskan oksigen.</p><h5>✅ Mengapa jawapan D betul</h5><p>Fotosintesis menggunakan gas karbon dioksida sebagai bahan tindak balas mentah untuk menghasilkan makanan, secara langsung menyingkirkannya daripada atmosfera.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Respirasi sel oleh haiwan, tumbuhan dan mikrob menggunakan gas oksigen dan membebaskan karbon dioksida ke atmosfera.</li><li><b>B</b> — Pembakaran bahan api fosil bertindak mengoksidakan sebatian hidrokarbon dan melepaskan sejumlah besar karbon dioksida ke udara.</li><li><b>C</b> — Penguraian jirim organik reput oleh organisma pengurai membebaskan gas karbon dioksida kembali ke atmosfera melalui respirasi pengurai.</li></ul><h5>📌 Ingat</h5><p>Fotosintesis ialah satu-satunya proses semula jadi yang menyingkirkan karbon dioksida daripada atmosfera, manakala respirasi, pembakaran dan penguraian menambahkannya.</p>",
"<h5>🧠 Konsep utama</h5><p>Simbiosis menerangkan perhubungan rapat antara dua spesies organisma berlainan yang hidup bersama dalam satu ekosistem. Bentuk interaksi simbiotik merangkumi mutualisme, komensalisme dan parasitisme. Dalam interaksi parasitisme, satu organisma yang dikenali sebagai parasit memperoleh faedah (nutrien, air atau perlindungan), manakala organisma yang satu lagi yang dipanggil perumah mengalami kemudaratan atau kerugian. Tumbuhan tali puteri (<i>Cuscuta</i>) merupakan sejenis tumbuhan parasit tanpa klorofil yang melilit batang pokok perumah dan menembuskan akar khas (haustorium) ke dalam berkas vaskular pokok tersebut untuk menyerap air dan bahan makanan tercerna, menyebabkan pokok perumah kehilangan nutrien dan menjadi lemah.</p><h5>✅ Mengapa jawapan B betul</h5><p>Tali puteri mendapat keuntungan dengan menyerap nutrien daripada pokok perumah manakala pokok perumah mengalami kemudaratan, menepati definisi interaksi parasitisme.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Mutualisme ialah interaksi yang menguntungkan kedua-dua organisma yang terlibat secara bersama, seperti interaksi kulat dan alga dalam liken.</li><li><b>C</b> — Komensalisme ialah interaksi di mana satu organisma mendapat manfaat manakala perumah tidak mendapat untung dan tidak mengalami sebarang kemudaratan.</li><li><b>D</b> — Pemangsaan melibatkan pemangsa yang memburu, menangkap dan membunuh mangsanya dengan serta-merta untuk dijadikan sumber makanan.</li></ul><h5>📌 Ingat</h5><p>Interaksi organisma: Mutualisme (+/+), Komensalisme (+/0), Parasitisme (+/-). Parasit memudaratkan perumah tanpa membunuhnya secara serta-merta.</p>",
"<h5>🧠 Konsep utama</h5><p>Populasi pemangsa bergantung pada bekalan mangsa sebagai makanan. Apabila bilangan mangsa menurun, pemangsa mungkin kekurangan makanan; selepas suatu tempoh, kadar pembiakan boleh menurun dan kadar kematian boleh meningkat. Pada graf, masa ialah pemboleh ubah pada paksi mengufuk dan populasi ialah pemboleh ubah pada paksi menegak. Garis penuh mewakili rusa, manakala garis putus-putus mewakili harimau. Populasi rusa mencapai puncak sekitar tahun ke-2 lalu menurun hingga tahun ke-5; populasi harimau mula menurun selepas tahun ke-4.</p><h5>✅ Mengapa jawapan A betul</h5><p>Penurunan bilangan rusa lebih awal mengurangkan sumber makanan harimau. Kesan ini boleh menjelaskan penurunan populasi harimau yang menyusul selepas tahun ke-4.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Graf menunjukkan bilangan rusa menurun tetapi tidak menunjukkan punca seperti penghijrahan beramai-ramai.</li><li><b>C</b> — Graf tidak menunjukkan bahawa harimau berhenti memburu rusa; kekurangan mangsa ialah penjelasan yang disokong oleh corak kedua-dua populasi.</li><li><b>D</b> — Bilangan rusa sedang menurun sebelum populasi harimau menurun, bukannya bertambah terlalu banyak.</li></ul><h5>📌 Ingat</h5><p>Dalam hubungan mangsa dan pemangsa, perubahan populasi pemangsa lazimnya menyusul selepas perubahan populasi mangsa.</p>",
"<h5>🧠 Konsep utama</h5><p>Perubahan pada jirim dikelaskan kepada perubahan fizikal dan perubahan kimia. Perubahan fizikal hanya melibatkan perubahan pada sifat luaran seperti saiz, bentuk atau keadaan jirim tanpa menghasilkan sebarang bahan baharu, tidak melibatkan perubahan komposisi molekul dan prosesnya mudah berbalik (contohnya peleburan, pendidihan dan pelarutan). Sebaliknya, perubahan kimia ialah proses di mana ikatan kimia terputus dan terbentuk semula menghasilkan satu atau lebih bahan baharu yang mempunyai komposisi kimia serta sifat yang berbeza daripada bahan asal, dan perubahan ini lazimnya tidak berbalik secara kaedah fizikal. Apabila susu menjadi masam, bakteria menapai laktosa menghasilkan asid laktik baharu yang mengubah sifat kimia dan rasa susu tersebut secara kekal.</p><h5>✅ Mengapa jawapan C betul</h5><p>Susu menjadi masam ialah perubahan kimia kerana tindak balas penapaian bakteria membentuk bahan baharu (asid laktik) yang tidak boleh diterbalikkan semula menjadi susu segar.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Lilin melebur merupakan perubahan fizikal kerana hanya keadaan jirim lilin bertukar daripada pepejal kepada cecair dan membeku semula apabila sejuk.</li><li><b>B</b> — Melarutkan garam ke dalam air ialah perubahan fizikal kerana tiada ikatan kimia baharu terbentuk dan garam boleh diperoleh semula melalui penyejatan.</li><li><b>D</b> — Pembekuan air menjadi ais hanyalah perubahan fizikal fasa jirim cecair kepada pepejal yang mengekalkan formula molekul air (H₂O).</li></ul><h5>📌 Ingat</h5><p>Perubahan fizikal: tiada bahan baharu terhasil, berbalik. Perubahan kimia: bahan baharu terbentuk dengan sifat berbeza, tidak berbalik secara fizikal.</p>",
"<h5>🧠 Konsep utama</h5><p>Bahan kimia boleh wujud dalam bentuk unsur, sebatian atau campuran. Unsur ialah bahan paling ringkas yang terdiri daripada satu jenis atom sahaja dan tidak boleh dipecahkan lagi secara kimia. Sebatian pula terhasil daripada gabungan dua atau lebih unsur berlainan jenis yang terikat bersama secara kimia mengikut nisbah tertentu. Semasa tindak balas kimia pembentukan sebatian, konfigurasi elektron berubah melalui perkongsian atau pemindahan elektron bagi membentuk ikatan kimia baharu. Akibatnya, sifat fizikal dan kimia bagi sebatian yang terhasil adalah sama sekali berbeza daripada sifat unsur-unsur juzuk asalnya. Natrium ialah logam reaktif dan klorin ialah gas toksik, namun sebatian natrium klorida (garam dapur) mempunyai struktur ion yang stabil dan selamat dimakan.</p><h5>✅ Mengapa jawapan A betul</h5><p>Pembentukan natrium klorida membuktikan bahawa sesuatu sebatian mempunyai sifat-sifat baharu yang berbeza sama sekali daripada sifat unsur-unsur yang membentuknya.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Natrium klorida ialah sebatian kimia berikat ionik, bukan suatu campuran fizikal yang tidak berpadu.</li><li><b>C</b> — Unsur-unsur dalam sebatian terikat secara kimia dan tidak boleh dipisahkan melalui kaedah fizikal mudah seperti penurasan.</li><li><b>D</b> — Sebatian tidak mempunyai sifat yang sama dengan unsur pembentuknya kerana penyusunan elektron dan ikatan kimianya telah berubah sepenuhnya.</li></ul><h5>📌 Ingat</h5><p>Sifat sebatian berbeza daripada unsur pembentuknya: gabungan kimia mengubah sifat asal unsur menghasilkan bahan baharu dengan ciri tersendiri.</p>",
"<h5>🧠 Konsep utama</h5><p>Bahan api fosil yang mengandungi sulfur membebaskan sulfur dioksida apabila dibakar. Gas ini larut dalam titisan air di atmosfera dan menghasilkan bahan berasid; sebahagiannya juga boleh teroksida lalu menghasilkan asid sulfurik. Apabila hujan menjadi lebih berasid, tumbuhan dan hidupan akuatik boleh terjejas. Hujan asid juga menghakis bahan binaan seperti batu kapur serta mempercepat kakisan logam.</p><h5>✅ Mengapa jawapan D betul</h5><p>Sulfur dioksida yang larut dalam air hujan menyumbang kepada hujan asid, yang boleh merosakkan tumbuhan dan bangunan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Penipisan lapisan ozon terutama dikaitkan dengan bahan seperti klorofluorokarbon, bukan sulfur dioksida dalam air hujan.</li><li><b>B</b> — Pembakaran menggunakan oksigen; sulfur dioksida tidak menambah oksigen di udara.</li><li><b>C</b> — Lapisan debu berpunca daripada zarah pepejal yang mendap, sedangkan soalan bertanya kesan gas sulfur dioksida yang larut dalam hujan.</li></ul><h5>📌 Ingat</h5><p>Gas sulfur dioksida dalam air hujan → hujan asid → kerosakan tumbuhan dan hakisan bahan binaan.</p>",
"<h5>🧠 Konsep utama</h5><p>Keterlarutan ialah jisim maksimum zat terlarut yang boleh larut dalam sejumlah pelarut pada suhu tertentu sehingga larutan tepu terbentuk. Dalam jadual ini, suhu air ialah pemboleh ubah dimanipulasi, manakala jisim maksimum gula yang larut ialah pemboleh ubah bergerak balas. Jisim air, iaitu 100 g, dan jenis gula dimalarkan supaya perbandingan adil. Bacaan jadual ialah 204 g pada 20 °C, 238 g pada 40 °C, 287 g pada 60 °C dan 362 g pada 80 °C. Apabila suhu meningkat, keseimbangan pelarutan gula membolehkan lebih banyak gula larut dalam air.</p><h5>✅ Mengapa jawapan A betul</h5><p>Jisim maksimum gula yang larut dalam 100 g air meningkat daripada 204 g kepada 362 g apabila suhu naik daripada 20 °C kepada 80 °C. Maka keterlarutan gula bertambah dengan suhu dalam julat yang diuji.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Semua bacaan jisim gula meningkat apabila suhu meningkat, bukan berkurang.</li><li><b>C</b> — Bacaan pada 20 °C dan 80 °C berbeza sebanyak 158 g; suhu mempengaruhi keterlarutan gula.</li><li><b>D</b> — Pada 20 °C, sebanyak 204 g gula boleh larut dalam 100 g air.</li></ul><h5>📌 Ingat</h5><p>Untuk membandingkan keterlarutan pada suhu berlainan, kekalkan jisim pelarut yang sama.</p>",
"<h5>🧠 Konsep utama</h5><p>Di dalam rongga mulut manusia, bakteria mulut menguraikan cebisan karbohidrat dan gula daripada sisa makanan yang terperangkap pada celah gigi melalui proses penapaian. Tindak balas biokimia ini menghasilkan asid organik seperti asid laktik yang menurunkan nilai pH di dalam rongga mulut menjadi berasid (pH di bawah 5.5). Persekitaran asid ini akan melarutkan garam kalsium pada lapisan enamel gigi (demineralisasi), menyebabkan kaviti dan pereputan gigi berlaku. Ubat gigi diformulasikan bersifat alkali lemah supaya dapat bertindak balas dengan asid yang terhasil dalam tindak balas peneutralan (asid + alkali → garam + air). Tindak balas ini memulihkan nilai pH di dalam mulut ke tahap neutral dan seterusnya melindungi enamel gigi daripada terus dihakis.</p><h5>✅ Mengapa jawapan B betul</h5><p>Sifat alkali lemah dalam ubat gigi bertindak meneutralkan asid yang dihasilkan oleh bakteria mulut, menghentikan hakisan ke atas enamel gigi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Ubat gigi tidak bertujuan membunuh semua bakteria mulut kerana flora bakteria normal diperlukan untuk mengekalkan keseimbangan mikrobiom mulut.</li><li><b>C</b> — Karang gigi atau kalkulus yang telah mengeras tidak dapat dilarutkan oleh alkali lemah ubat gigi dan memerlukan penskaleran mekanikal di klinik gigi.</li><li><b>D</b> — Buih dihasilkan oleh agen surfaktan khas seperti natrium lauril sulfat, bukannya ditentukan semata-mata oleh sifat alkali lemah ramuannya.</li></ul><h5>📌 Ingat</h5><p>Aplikasi peneutralan: Sisa makanan + bakteria menghasilkan asid → alkali lemah dalam ubat gigi meneutralkan asid tersebut untuk mencegah kerosakan gigi.</p>",
"<h5>🧠 Konsep utama</h5><p>Siri kereaktifan logam menyusun unsur logam mengikut kecenderungan kereaktifannya untuk bertindak balas dengan oksigen bagi membentuk oksida logam. Unsur yang lebih reaktif mempunyai afiniti yang lebih tinggi terhadap oksigen dan mampu menyingkirkan oksigen daripada oksida unsur yang kurang reaktif melalui tindak balas penurunan. Karbon diletakkan di dalam siri kereaktifan logam untuk menentukan kaedah pengekstrakan logam. Sekiranya campuran karbon dan oksida logam tidak menunjukkan sebarang perubahan apabila dipanaskan, ini bermakna logam tersebut lebih reaktif daripada karbon (X > karbon). Sebaliknya, jika karbon berjaya menyingkirkan oksigen daripada oksida logam, maka karbon lebih reaktif daripada logam tersebut (karbon > Y dan karbon > Z). Dalam eksperimen seterusnya, serbuk logam Y dapat menurunkan oksida Z menghasilkan logam Z, membuktikan bahawa logam Y lebih reaktif daripada logam Z (Y > Z).</p><h5>✅ Mengapa jawapan A betul</h5><p>X lebih reaktif daripada karbon, karbon lebih reaktif daripada Y dan Z, dan Y lebih reaktif daripada Z. Maka susunan dari paling reaktif ialah X, karbon, Y, Z.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Susunan Z, Y, karbon, X ialah urutan songsang iaitu daripada yang paling kurang reaktif kepada yang paling reaktif.</li><li><b>C</b> — Meletakkan Z mendahului Y adalah salah kerana logam Y berjaya menyesarkan oksigen daripada oksida Z, membuktikan Y lebih reaktif daripada Z.</li><li><b>D</b> — Karbon tidak boleh mendahului X kerana karbon gagal menurunkan oksida X (tiada perubahan semasa pemanasan).</li></ul><h5>📌 Ingat</h5><p>Unsur yang lebih reaktif merebut oksigen daripada oksida unsur yang kurang reaktif. Tiada tindak balas berlaku bermakna logam dalam oksida itu lebih reaktif.</p>",
"<h5>🧠 Konsep utama</h5><p>Termokimia mengkaji perubahan tenaga haba yang mengiringi tindak balas kimia atau proses fizik. Tindak balas terbahagi kepada proses eksotermik dan proses endotermik. Tindak balas eksotermik membebaskan tenaga haba ke persekitaran semasa pembentukan ikatan kimia baharu, menyebabkan peningkatan suhu di persekitaran (contohnya tindak balas pembakaran, respirasi sel, dan peneutralan asid-alkali). Sebaliknya, tindak balas endotermik menyerap tenaga haba atau cahaya daripada persekitaran untuk memutuskan ikatan kimia bahan tindak balas, menyebabkan suhu persekitaran menurun atau memerlukan bekalan tenaga berterusan dari luar. Semasa proses fotosintesis, molekul klorofil menyerap tenaga cahaya daripada Matahari untuk menukarkan karbon dioksida dan air kepada molekul glukosa dan oksigen.</p><h5>✅ Mengapa jawapan C betul</h5><p>Fotosintesis menyerap tenaga cahaya dari persekitaran untuk menjalankan tindak balas sintesis glukosa, menepati ciri proses endotermik.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Respirasi sel ialah proses biokimia eksotermik yang mengoksidakan glukosa dan membebaskan tenaga haba serta ATP kepada sel.</li><li><b>B</b> — Pembakaran kayu ialah tindak balas pengoksidaan eksotermik cergas yang membebaskan sejumlah besar haba dan cahaya ke persekitaran.</li><li><b>D</b> — Peneutralan antara asid dan alkali merupakan tindak balas eksotermik yang membebaskan haba peneutralan lalu menaikkan suhu larutan.</li></ul><h5>📌 Ingat</h5><p>Endotermik = menyerap haba atau tenaga (contoh: fotosintesis, peleburan, penguraian terma). Eksotermik = membebaskan haba (pembakaran, respirasi, peneutralan).</p>",
"<h5>🧠 Konsep utama</h5><p>Rintangan mengukur halangan terhadap aliran arus elektrik. Hukum Ohm memberikan hubungan <i>V</i> = <i>I</i> × <i>R</i>, maka <i>R</i> = <i>V</i> ÷ <i>I</i>. Unit beza keupayaan ialah volt (V), arus ialah ampere (A), dan rintangan ialah ohm (Ω). Pada graf <i>V</i> melawan <i>I</i>, kecerunan garis lurus ialah rintangan. Baca titik pada graf: <i>I</i> = 0.4 A dan <i>V</i> = 2.0 V.</p><h5>✅ Mengapa jawapan C betul</h5><p><i>R</i> = 2.0 V ÷ 0.4 A = 5 Ω. Oleh itu, rintangan perintang ialah 5 Ω.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — 0.2 terhasil daripada 0.4 A ÷ 2.0 V. Itu ialah <i>I</i> ÷ <i>V</i> dengan unit A/V, bukan rintangan dalam Ω.</li><li><b>B</b> — 2.5 Ω boleh terhasil jika tersalah baca beza keupayaan sebagai 1.0 V pada arus 0.4 A; titik sebenar menunjukkan 2.0 V.</li><li><b>D</b> — 10 Ω boleh terhasil jika mengambil 4.0 V daripada titik pada 0.8 A tetapi masih membahaginya dengan 0.4 A. Kedua-dua bacaan mesti diambil daripada titik yang sama.</li></ul><h5>📌 Ingat</h5><p>Untuk mencari kecerunan graf <i>V</i> melawan <i>I</i>, gunakan sepasang bacaan pada titik yang sama: volt ÷ ampere = ohm.</p>",
"<h5>🧠 Konsep utama</h5><p>Fius ialah komponen keselamatan elektrik yang dipasang pada dawai hidup di dalam palam atau kotak agihan bagi melindungi peralatan daripada arus lampau. Fius mengandungi seutas wayar halus pendek dengan takat lebur rendah yang akan melebur dan memutuskan sambungan litar apabila arus yang mengalir melampaui kadaran fius. Hubungan antara kuasa elektrik (<i>P</i>), beza keupayaan bekalan (<i>V</i>) dan arus operasi elektrik (<i>I</i>) diterangkan oleh formula:<br><i>P</i> = <i>V</i> × <i>I</i>, maka <i>I</i> = <i>P</i> ÷ <i>V</i>.<br>Bagi cerek elektrik yang dilabelkan 240 V dan 2200 W, arus elektrik normal yang melaluinya ialah:<br><i>I</i> = 2200 W ÷ 240 V ≈ 9.17 A.<br>Kadaran fius yang dipilih mestilah mempunyai nilai piawai yang sedikit lebih tinggi daripada arus operasi biasa ini supaya tidak lebur semasa penggunaan lazim.</p><h5>✅ Mengapa jawapan D betul</h5><p>Arus operasi cerek elektrik ialah kira-kira 9.17 A, maka nilai kadaran fius piawai yang paling selamat dan sesuai digunakan ialah 13 A.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Fius 1 A mempunyai kadaran yang jauh lebih kecil daripada 9.17 A dan akan serta-merta melebur sebaik suis cerek dihidupkan.</li><li><b>B</b> — Fius 3 A juga jauh lebih kecil daripada arus operasi normal 9.17 A dan akan terus putus apabila arus mengalir.</li><li><b>C</b> — Fius 5 A tidak dapat menampung arus cerek sebanyak 9.17 A dan akan terbakar serta memutuskan litar elektrik secara serta-merta.</li></ul><h5>📌 Ingat</h5><p>Pilih kadaran fius piawai (1 A, 3 A, 5 A, 13 A) yang sedikit lebih besar daripada arus operasi normal peranti (<i>I</i> = <i>P</i> ÷ <i>V</i>).</p>",
"<h5>🧠 Konsep utama</h5><p>Tuas ialah mesin ringkas yang terdiri daripada sebatang rod tegar yang boleh berputar bebas pada satu titik sokongan yang dipanggil fulkrum. Tuas dikelaskan kepada tiga kelas bergantung kepada kedudukan relatif antara beban, fulkrum dan daya: Tuas kelas pertama mempunyai fulkrum di bahagian tengah di antara beban dan daya (B-F-D). Tuas kelas kedua mempunyai beban di bahagian tengah di antara fulkrum dan daya (F-B-D). Tuas kelas ketiga mempunyai daya di bahagian tengah di antara fulkrum dan beban (F-D-B). Kereta sorong ialah tuas kelas kedua kerana rodanya bertindak sebagai fulkrum di hujung hadapan, beban berada di dalam bakul di bahagian tengah, dan daya dikenakan oleh tangan pengguna pada pemegang di hujung belakang.</p><h5>✅ Mengapa jawapan C betul</h5><p>Pemecah kacang ialah tuas kelas kedua kerana fulkrum berada pada engsel hujung, kacang (beban) diletakkan di tengah, dan daya dikenakan pada hujung pemegang.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Gunting ialah tuas kelas pertama kerana fulkrum (skru paksi) terletak di bahagian tengah di antara bilah pemotong dan pemegang.</li><li><b>B</b> — Penyepit makanan ialah tuas kelas ketiga kerana daya dikenakan oleh jari di bahagian tengah antara engsel (fulkrum) dan beban di hujung.</li><li><b>D</b> — Jongkang-jongket ialah tuas kelas pertama kerana titik fulkrum terletak di bahagian tengah menyokong papan di antara kedua-dua hujung.</li></ul><h5>📌 Ingat</h5><p>Mnemonic tuas (kedudukan yang berada di tengah): Kelas 1 = Fulkrum di tengah; Kelas 2 = Beban di tengah; Kelas 3 = Daya di tengah.</p>",
"<h5>🧠 Konsep utama</h5><p>Pemindahan haba melalui bendalir (cecair dan gas) berlaku secara perolakan yang dipacu oleh perubahan ketumpatan akibat perbezaan suhu. Darat diperbuat daripada batu dan tanah yang mempunyai muatan haba tentu yang lebih rendah berbanding air laut. Ini bermakna daratan menyerap haba dengan lebih cepat dan menjadi panas lebih cepat daripada air laut pada waktu siang apabila disinari Matahari. Udara di atas daratan yang panas akan mengembang, ketumpatannya berkurang lalu naik ke bahagian atas atmosfera, mewujudkan kawasan tekanan udara rendah di darat. Udara di atas permukaan laut yang lebih sejuk dan tumpat (bertekanan tinggi) akan bergerak mengalir masuk ke daratan untuk memenuhi ruang udara yang telah naik itu. Pergerakan arus udara ini dikenali sebagai fenomena bayu laut.</p><h5>✅ Mengapa jawapan A betul</h5><p>Darat memanas lebih pantas pada waktu siang menyebabkan udara panas di atasnya naik, membolehkan udara sejuk dari laut bertiup ke darat sebagai bayu laut.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Air laut mempunyai muatan haba tentu yang tinggi, menjadikannya memanas jauh lebih perlahan daripada daratan pada waktu siang.</li><li><b>C</b> — Keadaan darat menyejuk lebih pantas berlaku pada waktu malam, menghasilkan tiupan bayu darat dari daratan ke laut.</li><li><b>D</b> — Udara di atas daratanlah yang lebih panas dan naik ke atas pada waktu siang, bukannya udara di atas laut.</li></ul><h5>📌 Ingat</h5><p>Bayu laut (waktu siang): darat lebih panas → udara panas darat naik → angin sejuk bertiup dari laut ke darat. Muatan haba tentu darat &lt; laut.</p>",
"<h5>🧠 Konsep utama</h5><p>Warna suatu objek legap ditentukan oleh komponen warna cahaya yang dipantulkan oleh permukaannya ke mata pemerhati. Objek legap mengandungi pigmen pewarna tertentu yang menyerap sebahagian spektrum warna cahaya dan memantulkan warna cahaya yang sepadan dengannya. Baju yang berwarna merah mengandungi pigmen merah yang hanya akan memantulkan gelombang cahaya merah, manakala semua warna primer lain seperti cahaya biru dan hijau akan diserap sepenuhnya oleh pigmen tersebut. Cahaya biru merupakan salah satu daripada warna primer cahaya. Apabila baju merah diletakkan di dalam bilik gelap yang hanya disinari oleh cahaya biru, tiada sebarang komponen cahaya merah yang jatuh ke atas baju tersebut untuk dipantulkan. Akibatnya, baju merah menyerap seluruh cahaya biru dan tiada cahaya yang dipantulkan ke mata, menyebabkan baju kelihatan hitam.</p><h5>✅ Mengapa jawapan D betul</h5><p>Baju merah menyerap cahaya biru dan ketiadaan cahaya merah menyebabkan tiada cahaya dipantulkan ke retina mata, lalu baju kelihatan berwarna hitam.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Baju hanya akan kelihatan merah jika terdapat sumber cahaya merah atau cahaya putih (mengandungi cahaya merah) yang menyinarinya.</li><li><b>B</b> — Baju merah tidak dapat memantulkan cahaya biru kerana pigmen warna merah menyerap gelombang warna cahaya biru.</li><li><b>C</b> — Magenta ialah warna sekunder yang terhasil apabila cahaya merah dan biru bergabung serentak pada permukaan putih, bukan pantulan pada kain merah.</li></ul><h5>📌 Ingat</h5><p>Objek legap hanya memantulkan warna asalnya dan menyerap warna-warna lain. Jika warna asalnya tiada dalam cahaya tuju, objek akan kelihatan hitam.</p>",
"<h5>🧠 Konsep utama</h5><p>Gelombang bunyi ialah gelombang mekanikal membujur yang dihasilkan oleh objek yang bergetar. Perambatan gelombang bunyi memerlukan kehadiran medium berjirim (sama ada pepejal, cecair atau gas) kerana tenaga bunyi dipindahkan melalui getaran berantai dan perlanggaran zarah-zarah jirim secara mampatan dan renggangan. Sebaliknya, gelombang cahaya ialah gelombang elektromagnet yang tidak memerlukan medium dan boleh merambat menerusi ruang vakum. Dalam eksperimen ini, apabila udara di dalam balang kaca dipam keluar beransur-ansur sehingga membentuk ruang vakum, zarah udara yang memindahkan gelombang bunyi tidak lagi wujud. Oleh itu, bunyi loceng menjadi semakin senyap dan akhirnya tidak kedengaran, walaupun pengetuk loceng masih jelas kelihatan bergetar.</p><h5>✅ Mengapa jawapan A betul</h5><p>Ketiadaan bunyi apabila udara dipam keluar membuktikan secara tuntas bahawa gelombang bunyi memerlukan medium jirim untuk merambat.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Pemerhatian eksperimen menunjukkan bahawa pengetuk loceng masih terus bergetar secara mekanikal walaupun di dalam balang tanpa udara.</li><li><b>C</b> — Cahaya pengetuk yang bergetar masih boleh dilihat menembusi balang kaca membuktikan cahaya tidak memerlukan medium jirim untuk merambat.</li><li><b>D</b> — Bunyi tidak dapat merambat sama sekali di dalam vakum, bukannya merambat dengan lebih laju.</li></ul><h5>📌 Ingat</h5><p>Bunyi = gelombang mekanikal (memerlukan medium berjirim untuk merambat; senyap dalam vakum). Cahaya = gelombang elektromagnet (boleh melalui vakum).</p>",
"<h5>🧠 Konsep utama</h5><p>Kuasa ialah kerja yang dilakukan setiap saat: <i>P</i> = <i>W</i> ÷ <i>t</i>. Ketika murid menaiki tangga, kerja melawan graviti bersamaan dengan pertambahan tenaga keupayaan graviti, iaitu <i>W</i> = <i>m</i> × <i>g</i> × <i>h</i>. Daripada soalan, jisim <i>m</i> = 50 kg, pecutan graviti <i>g</i> = 10 N kg⁻¹, tinggi <i>h</i> = 4 m dan masa <i>t</i> = 10 s. Berat murid ialah 50 kg × 10 N kg⁻¹ = 500 N. Kerja ialah 500 N × 4 m = 2000 J.</p><h5>✅ Mengapa jawapan B betul</h5><p>Kuasa = 2000 J ÷ 10 s = 200 W. Jadi jawapannya ialah 200 W.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — 20 terhasil daripada 50 × 4 ÷ 10 jika faktor graviti 10 N kg⁻¹ tertinggal.</li><li><b>C</b> — 500 ialah berat murid dalam unit newton (N), diperoleh daripada 50 × 10; itu bukan kuasa dalam watt.</li><li><b>D</b> — 2000 ialah kerja dalam joule (J). Untuk mendapat kuasa, kerja itu masih perlu dibahagi dengan masa 10 s.</li></ul><h5>📌 Ingat</h5><p>Bezakan berat (N), kerja (J) dan kuasa (W); kuasa sentiasa melibatkan masa.</p>",
"<h5>🧠 Konsep utama</h5><p>Sinar gama ialah sinaran elektromagnet yang terhasil daripada proses radioaktif. Berbanding zarah alfa dan beta, sinar gama mempunyai kuasa penembusan paling tinggi tetapi kuasa pengionan paling rendah. Sinar ini dapat menembusi bungkusan plastik dan merosakkan bahan genetik mikroorganisma, lalu mensteril picagari yang masih dibungkus. Kaedah ini tidak memerlukan pemanasan hingga meleburkan plastik atau pembukaan bungkusan. Bahan pelindung seperti plumbum atau konkrit tebal digunakan untuk mengurangkan pendedahan kepada sinar gama.</p><h5>✅ Mengapa jawapan B betul</h5><p>Sinar gama dapat menembusi bungkusan dan membunuh mikroorganisma pada picagari.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Penyinaran untuk pensterilan tidak menjadikan picagari radioaktif secara kekal.</li><li><b>C</b> — Tujuan sinar gama ialah merosakkan mikroorganisma, bukan memanaskan picagari sehingga melebur.</li><li><b>D</b> — Bungkusan plastik tidak menghalang sinar gama sepenuhnya; sinar itu dapat menembusinya.</li></ul><h5>📌 Ingat</h5><p>Alfa paling kuat mengion tetapi paling lemah menembusi; gama paling kuat menembusi tetapi paling lemah mengion.</p>",
"<h5>🧠 Konsep utama</h5><p>Matahari terdiri daripada lapisan struktur dalam (teras, zon radiasi dan zon perolakan) serta lapisan atmosfera Matahari di bahagian luar. Atmosfera Matahari dibahagikan kepada tiga lapisan utama: fotosfera, kromosfera dan korona. Fotosfera ialah lapisan atmosfera Matahari yang paling dalam dan paling tumpat dengan ketebalan kira-kira 400 km dan suhu sekitar 6000 K. Lapisan fotosfera inilah yang kelihatan sebagai permukaan cakera kuning berkilauan Matahari apabila dilihat dari Bumi (dengan menggunakan penuras suria yang selamat). Fotosfera memancarkan hampir keseluruhan spektrum sinaran cahaya tampak yang menerangi sistem suria. Fenomena tompok matahari dan granulasi permukaan juga terbentuk di atas lapisan fotosfera ini.</p><h5>✅ Mengapa jawapan C betul</h5><p>Fotosfera ialah lapisan permukaan bercahaya yang memancarkan cahaya tampak Matahari yang sampai ke mata kita di Bumi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Teras merupakan bahagian pusat paling dalam tempat berlangsungnya tindak balas pelakuran nuklear hidrogen kepada helium, bukan lapisan permukaan luar.</li><li><b>B</b> — Korona ialah lapisan terluar atmosfera Matahari yang membentuk lingkaran gas putih kebiruan halus yang hanya kelihatan semasa gerhana matahari penuh.</li><li><b>D</b> — Kromosfera ialah lapisan atmosfera di atas fotosfera yang kelihatan sebagai lingkaran merah cerah semasa fasa gerhana matahari.</li></ul><h5>📌 Ingat</h5><p>Lapisan Matahari: Teras (pusat nuklear) → Fotosfera (permukaan cahaya tampak) → Kromosfera (lapisan merah) → Korona (lapisan halo putih terluar).</p>",
"<h5>🧠 Konsep utama</h5><p>Komet terdiri daripada ais, habuk dan batuan yang mengorbit Matahari. Apabila komet menghampiri Matahari, aisnya memejalwap dan membebaskan gas serta habuk yang membentuk koma dan ekor. Angin suria menolak gas terion, manakala tekanan sinaran Matahari menolak habuk. Oleh itu, kedua-dua jenis ekor secara umum menghala menjauhi Matahari. Arah ekor bergantung terutamanya pada kedudukan Matahari, bukan semata-mata pada arah gerakan komet.</p><h5>✅ Mengapa jawapan D betul</h5><p>Angin suria dan sinaran Matahari menolak bahan yang keluar daripada komet sehingga ekornya menghala menjauhi Matahari.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Komet bergerak menghampiri Matahari pada sebahagian orbitnya dan menjauhi Matahari pada bahagian lain. Ekornya tetap menghala menjauhi Matahari dalam kedua-dua keadaan.</li><li><b>B</b> — Graviti Musytari boleh mempengaruhi orbit komet, tetapi bukan punca utama arah ekornya.</li><li><b>C</b> — Ekor komet ialah gas dan habuk yang terlepas apabila ais memejalwap, bukan asap pembakaran.</li></ul><h5>📌 Ingat</h5><p>Ekor komet menunjuk menjauhi Matahari, walaupun komet sedang bergerak ke arah Matahari.</p>",
"<h5>🧠 Konsep utama</h5><p>Tsunami merupakan siri gelombang ombak lautan berkuasa besar yang berpunca daripada anjakan jisim air laut secara mengejut, biasanya akibat gempa bumi sesar menegak di dasar laut, letusan gunung berapi bawah laut atau gelongsoran tanah dasar lautan. Sebelum puncak gelombang tsunami pertama melanda pesisir pantai, bahagian palung (lembah) gelombang sering tiba terlebih dahulu di pantai. Ini mengakibatkan paras air laut menyurut secara mendadak dan amat drastik jauh ke tengah lautan dalam masa beberapa minit sahaja, mendedahkan dasar laut yang biasanya ditenggelami air. Fenomena air laut surut yang luar biasa ini merupakan tanda amaran semula jadi bahawa ombak pemusnah gergasi tsunami bakal menghempas daratan dalam masa yang amat singkat.</p><h5>✅ Mengapa jawapan C betul</h5><p>Penurunan paras air laut secara mendadak selepas gempa bumi dasar laut ialah petanda tsunami akan melanda, maka penduduk perlu segera berpindah ke kawasan tanah tinggi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Berkumpul di tepi pantai adalah tindakan yang membawa maut kerana ombak tsunami pertama yang laju dan kuat boleh melanda pada bila-bila masa.</li><li><b>B</b> — Mengutip hidupan laut yang terdampar di dasar laut yang terdedah menyebabkan penduduk terperangkap dan dihanyutkan oleh hempasan ombak tsunami gergasi.</li><li><b>D</b> — Berlindung di bawah meja di dalam rumah tepi pantai tidak memberi perlindungan terhadap hentaman dinding air tsunami yang mampu meruntuhkan seluruh bangunan.</li></ul><h5>📌 Ingat</h5><p>Tanda awal tsunami: Gempa bumi di dasar laut diikuti air laut surut pantas dan jauh dari pantai. Tindakan serta-merta: Berlari ke kawasan tanah tinggi yang jauh dari laut!</p>"]};
